import { useState, useEffect } from "react"
import {
  doc,
  onSnapshot,
  updateDoc,
  setDoc,
  getDoc,
  arrayUnion,
  serverTimestamp,
} from "firebase/firestore"
import { db } from "../firebase/config"

export interface ServiceItem {
  id: string
  label: string
  isActive: boolean
  order: number
}

export interface TaxSettings {
  GST: number
  QST: number
  updatedAt?: Date
  updatedBy?: string
}

interface SettingsResult {
  services: ServiceItem[]
  allServices: ServiceItem[]  // active + inactive, for Settings manager
  taxes: TaxSettings
  loading: boolean
  addService: (label: string) => Promise<void>
  updateService: (id: string, label: string) => Promise<void>
  toggleService: (id: string, isActive: boolean) => Promise<void>
  reorderServices: (orderedIds: string[]) => Promise<void>
  updateTaxes: (gst: number, qst: number, adminEmail: string) => Promise<void>
}

const DEFAULT_TAXES: TaxSettings = { GST: 5, QST: 9.975 }

function toSlug(label: string): string {
  return label.toLowerCase().replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "")
}

async function getFullList(): Promise<ServiceItem[]> {
  if (!db) return []
  const snap = await getDoc(doc(db, "settings", "services"))
  return (snap.data()?.list as ServiceItem[]) ?? []
}

export function useSettings(): SettingsResult {
  const [allServices, setAllServices] = useState<ServiceItem[]>([])
  const [taxes, setTaxes] = useState<TaxSettings>(DEFAULT_TAXES)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!db) {
      setLoading(false)
      return
    }

    let servicesLoaded = false
    let taxesLoaded = false
    const checkDone = () => {
      if (servicesLoaded && taxesLoaded) setLoading(false)
    }

    const unsubServices = onSnapshot(doc(db, "settings", "services"), snap => {
      const list = (snap.data()?.list as ServiceItem[]) ?? []
      setAllServices(list)
      servicesLoaded = true
      checkDone()
    })

    const unsubTaxes = onSnapshot(doc(db, "settings", "taxes"), snap => {
      const data = snap.data()
      if (data) {
        setTaxes({
          GST: data.GST ?? 5,
          QST: data.QST ?? 9.975,
          updatedAt: data.updatedAt?.toDate?.() ?? undefined,
          updatedBy: data.updatedBy ?? undefined,
        })
      }
      taxesLoaded = true
      checkDone()
    })

    return () => {
      unsubServices()
      unsubTaxes()
    }
  }, [])

  // Active services sorted by order — used by Phase 03 wizard
  const services = [...allServices]
    .filter(s => s.isActive)
    .sort((a, b) => a.order - b.order)

  async function addService(label: string): Promise<void> {
    if (!db) return
    const current = await getFullList()

    // Generate unique slug
    let slug = toSlug(label)
    const existing = current.map(s => s.id)
    if (existing.includes(slug)) {
      let i = 2
      while (existing.includes(`${slug}-${i}`)) i++
      slug = `${slug}-${i}`
    }

    const maxOrder = current.filter(s => s.isActive).reduce((m, s) => Math.max(m, s.order), -1)
    const newItem: ServiceItem = { id: slug, label, isActive: true, order: maxOrder + 1 }
    await updateDoc(doc(db, "settings", "services"), { list: arrayUnion(newItem) })
  }

  async function updateService(id: string, label: string): Promise<void> {
    if (!db) return
    const current = await getFullList()
    const updated = current.map(s => (s.id === id ? { ...s, label } : s))
    await updateDoc(doc(db, "settings", "services"), { list: updated })
  }

  async function toggleService(id: string, isActive: boolean): Promise<void> {
    if (!db) return
    const current = await getFullList()
    const updated = current.map(s => (s.id === id ? { ...s, isActive } : s))
    await updateDoc(doc(db, "settings", "services"), { list: updated })
  }

  async function reorderServices(orderedIds: string[]): Promise<void> {
    if (!db) return
    const current = await getFullList()
    const inactive = current.filter(s => !s.isActive)
    const active = orderedIds
      .map((id, idx) => {
        const found = current.find(s => s.id === id)
        return found ? { ...found, order: idx } : null
      })
      .filter(Boolean) as ServiceItem[]
    await updateDoc(doc(db, "settings", "services"), { list: [...active, ...inactive] })
  }

  async function updateTaxes(gst: number, qst: number, adminEmail: string): Promise<void> {
    if (!db) return
    await setDoc(doc(db, "settings", "taxes"), {
      GST: gst,
      QST: qst,
      updatedAt: serverTimestamp(),
      updatedBy: adminEmail,
    })
  }

  return {
    services,
    allServices,
    taxes,
    loading,
    addService,
    updateService,
    toggleService,
    reorderServices,
    updateTaxes,
  }
}
